"""RoboLab cubes_and_blocks_in_bin episode controller.
Run in the episode's Python environment; state is observed only through the client cameras and proprioception.
"""
import json, os, time
import numpy as np
from rcb_client import Robot

OUT = "/app/output"
R = Robot()
SPEC = R.spec()

def observe(depth=False, seconds=0.0, video="frames"):
    return R.get_obs(depth=depth, seconds=seconds, video=video)

def save_obs(obs, name="obs"):
    from PIL import Image
    d = os.path.join(OUT, name)
    os.makedirs(d, exist_ok=True)
    for cam, im in obs.last.items():
        Image.fromarray(im).save(os.path.join(d, f"{cam}.jpg"))
    if obs.last_depth:
        for cam, dep in obs.last_depth.items(): np.save(os.path.join(d, f"{cam}_depth.npy"), dep)
    with open(os.path.join(d, "meta.json"), "w") as f: json.dump(obs.meta, f, indent=2)
    return d

def ee_pose(xyz, quat_wxyz, gripper):
    return np.r_[np.asarray(xyz, float), np.asarray(quat_wxyz, float), float(gripper)]

def move_ee(points, dt=1/15, **kwargs):
    return R.submit("ee_pose", np.asarray(points, dtype=np.float32), dt=dt, **kwargs)

def move_joints(points, dt=1/15, **kwargs):
    return R.submit("joint_position", np.asarray(points, dtype=np.float32), dt=dt, **kwargs)

def tcp_now():
    """Current fingertip-centre pose [xyz, qwxyz], read from robot proprioception."""
    return np.asarray(R.get_obs(video="none").meta["proprio"]["now"][8:15], dtype=float)

def drive_ee(target, max_step=0.012, dt=1/15, video="mp4", note=""):
    """Move from measured TCP to one pose with small Cartesian increments."""
    target = np.asarray(target, dtype=float).reshape(8)
    now = np.asarray(R.get_obs(video="none").meta["proprio"]["now"], dtype=float)
    start = np.r_[now[8:15], now[15]]
    n = max(1, int(np.ceil(np.linalg.norm(target[:3]-start[:3]) / max_step)))
    # Keep the reset/downward grasp orientation throughout these motions.
    rows = np.tile(target, (n, 1))
    rows[:, :7] = np.linspace(start[:7], target[:7], n)
    rows[:, 7] = target[7]
    return R.submit("ee_pose", rows, dt=dt, video=video, note=note)

if __name__ == "__main__":
    print(json.dumps({"spec": SPEC, "status": R.status()}, indent=2))
    o = observe(depth=True)
    print(save_obs(o, "initial"))
